struct Patient {          // relation PATIENT
    string patientID;     // primary key
    string name;
    int    age;
    char   gender;        // domain: 'M', 'F', 'O'
    string phone;         // alternate key
    string city;
};

struct Appointment {      // relation APPOINTMENT
    string apptID;        // primary key
    string patientID;     // foreign key -> Patient::patientID
    string doctorID;      // foreign key -> Doctor::doctorID
    string date;
};

vector<Patient> patients;          // the relation's instance: one object per tuple
